/// Source: `oracle/oracle/codemp/game/w_saber.c:7958-7967`
pub fn G_PrettyCloseIGuess(
    a: f32,
    b: f32,
    tolerance: f32,
) -> qboolean {
    if (a - b) < tolerance && (a - b) > -tolerance {
        return 1;
    }
    0
}

